function fit(ctx, text, maxW, px, weight, minPx = 9) {
  let p = px;
  for (; p > minPx; p -= 1) { ctx.font = `${weight} ${p}px sans-serif`; if (ctx.measureText(text).width <= maxW) break; }
  return p;
}

function wrap2(ctx, text, maxW) {
  const words = String(text || '').split(/\s+/).filter(Boolean);
  const lines = [''];
  for (const w of words) {
    const t = lines[lines.length - 1] ? `${lines[lines.length - 1]} ${w}` : w;
    if (ctx.measureText(t).width <= maxW || !lines[lines.length - 1]) lines[lines.length - 1] = t;
    else if (lines.length < 2) lines.push(w);
    else { lines[1] = `${lines[1]}…`; break; }
  }
  return lines;
}

/** Paints card {icon, big, mid, small} at w x h: white on black (the glasses show light on dark). */
export function drawCard(ctx, w, h, card, { Path = globalThis.Path2D } = {}) {
  ctx.fillStyle = '#000'; ctx.fillRect(0, 0, w, h);
  const pad = Math.round(h * 0.06);
  ctx.strokeStyle = '#888'; ctx.lineWidth = Math.max(1, Math.round(h / 90));
  ctx.strokeRect(pad / 2, pad / 2, w - pad, h - pad);
  const ic = Math.round(h * 0.5);
  const ix = pad * 1.5, iy = Math.round((h - ic) / 2) - Math.round(h * 0.04);
  const d = ICONS[card.icon];
  if (d && Path) {
    ctx.save(); ctx.translate(ix, iy + ic); ctx.scale(ic / 960, ic / 960);
    ctx.fillStyle = '#fff'; ctx.fill(new Path(d)); ctx.restore();
  }
  const tx = ix + ic + pad * 1.5, tw = w - tx - pad * 1.5;
  ctx.fillStyle = '#fff'; ctx.textBaseline = 'alphabetic';
  const bp = fit(ctx, card.big || '', tw, Math.round(h * 0.17), 'bold');
  let y = Math.round(h * 0.36);
  ctx.fillText(card.big || '', tx, y);
  ctx.font = `${Math.round(h * 0.11)}px sans-serif`;
  ctx.fillStyle = '#ddd';
  for (const line of wrap2(ctx, card.mid, tw)) { y += Math.round(h * 0.14); ctx.fillText(line, tx, y); }
  if (card.small) {
    ctx.fillStyle = '#999';
    fit(ctx, card.small, w - pad * 3, Math.round(h * 0.085), 'normal', 7);
    ctx.fillText(card.small, pad * 1.5, h - pad * 1.4);
  }
  ctx.fillStyle = '#fff'; ctx.font = `bold ${Math.round(h * 0.08)}px sans-serif`;
  const tag = 'AD'; const tgw = ctx.measureText(tag).width;
  ctx.fillText(tag, w - pad * 1.5 - tgw, h - pad * 1.4);
  return bp;
}

function icon(ctx, name, x, y, size, Path) {
  const d = ICONS[name];
  if (!d || !Path) return;
  ctx.save(); ctx.translate(x, y + size); ctx.scale(size / 960, size / 960);
  ctx.fillStyle = '#fff'; ctx.fill(new Path(d)); ctx.restore();
}

/** 0.8.34 animated forecast: one frame of weatherFrameSpec() (ads.js) - now / next hours / tomorrow. A new page
 * slides in from the right (spec.slide 1 -> 0). White on black, like drawCard. */
export function drawWeather(ctx, w, h, spec, { Path = globalThis.Path2D } = {}) {
  ctx.fillStyle = '#000'; ctx.fillRect(0, 0, w, h);
  const pad = Math.round(h * 0.06);
  ctx.strokeStyle = '#888'; ctx.lineWidth = Math.max(1, Math.round(h / 90));
  ctx.strokeRect(pad / 2, pad / 2, w - pad, h - pad);
  const deg = (n) => (n == null ? '--' : `${n}°`);
  const foot = (text) => {
    if (!text) return;
    ctx.fillStyle = '#bbb'; fit(ctx, text, w - pad * 6, Math.round(h * 0.095), 'normal', 7);
    ctx.fillText(text, pad * 1.5, h - pad * 1.4);
  };
  ctx.save();
  const lw = ctx.lineWidth;
  ctx.beginPath(); ctx.rect(pad / 2 + lw, pad / 2 + lw, w - pad - 2 * lw, h - pad - 2 * lw); ctx.clip();   // a sliding page stays inside the frame
  ctx.translate(Math.round((spec.slide || 0) * w), 0);
  ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#999'; ctx.font = `bold ${Math.round(h * 0.085)}px sans-serif`;
  const head = spec.scene === 'hours' ? `${spec.place} · NEXT HOURS` : spec.scene === 'tomorrow' ? `${spec.place} · TOMORROW` : `${spec.place} · NOW`;
  fit(ctx, head, w - pad * 3, Math.round(h * 0.085), 'bold', 7);
  ctx.fillText(head, pad * 1.5, pad + Math.round(h * 0.09));
  if (spec.scene === 'now') {
    const ic = Math.round(h * 0.42);
    icon(ctx, spec.icon, pad * 1.5, Math.round(h * 0.2), ic, Path);
    const tx = pad * 3 + ic, tw = w - tx - pad * 1.5;
    ctx.fillStyle = '#fff';
    fit(ctx, deg(spec.temp), tw, Math.round(h * 0.3), 'bold');
    ctx.fillText(deg(spec.temp), tx, Math.round(h * 0.47));
    ctx.fillStyle = '#ddd'; fit(ctx, spec.text || '', tw, Math.round(h * 0.11), 'normal', 7);
    ctx.fillText(spec.text || '', tx, Math.round(h * 0.61));
    if (spec.feels != null) { ctx.fillStyle = '#bbb'; ctx.font = `${Math.round(h * 0.095)}px sans-serif`; ctx.fillText(`Feels like ${deg(spec.feels)}`, tx, Math.round(h * 0.74)); }
    foot(spec.hi != null || spec.lo != null ? `High ${deg(spec.hi)}   Low ${deg(spec.lo)}` : '');
  } else if (spec.scene === 'hours') {
    const cols = spec.hours || [];
    const cw = (w - pad * 3) / Math.max(1, cols.length);
    const ic = Math.round(h * 0.26);
    cols.forEach((c, i) => {
      const cx = pad * 1.5 + cw * i + cw / 2;
      ctx.fillStyle = '#ccc'; ctx.font = `${Math.round(h * 0.09)}px sans-serif`;
      let tw = ctx.measureText(c.h).width; ctx.fillText(c.h, cx - tw / 2, Math.round(h * 0.3));
      icon(ctx, c.icon, cx - ic / 2, Math.round(h * 0.34), ic, Path);
      ctx.fillStyle = '#fff'; ctx.font = `bold ${Math.round(h * 0.15)}px sans-serif`;
      tw = ctx.measureText(deg(c.temp)).width; ctx.fillText(deg(c.temp), cx - tw / 2, Math.round(h * 0.76));
    });
    const bits = [];
    if (spec.rain != null) bits.push(`Rain ${spec.rain}%`);
    if (spec.wind != null) bits.push(`Wind ${spec.wind} mph`);
    foot(bits.join('   '));
  } else {
    const t = spec.tom;
    if (t) {
      const ic = Math.round(h * 0.4);
      icon(ctx, t.icon, pad * 1.5, Math.round(h * 0.2), ic, Path);
      const tx = pad * 3 + ic, tw = w - tx - pad * 1.5;
      const hl = `${deg(t.hi)} / ${deg(t.lo)}`;
      ctx.fillStyle = '#fff'; fit(ctx, hl, tw, Math.round(h * 0.22), 'bold');
      ctx.fillText(hl, tx, Math.round(h * 0.44));
      ctx.fillStyle = '#ddd'; fit(ctx, t.text || '', tw, Math.round(h * 0.11), 'normal', 7);
      ctx.fillText(t.text || '', tx, Math.round(h * 0.59));
    }
    foot(spec.sunset ? `Sunset ${spec.sunset}` : '');
  }
  ctx.restore();
  ctx.font = `bold ${Math.round(h * 0.08)}px sans-serif`;
  const tag = 'AD'; const tgw = ctx.measureText(tag).width;
  const ty = h - pad * 1.4, th = Math.round(h * 0.08);
  ctx.fillStyle = '#000'; ctx.fillRect(w - pad * 2 - tgw, ty - th - 1, tgw + pad, th + 3);   // a sliding footer passes behind it
  ctx.fillStyle = '#fff'; ctx.fillText(tag, w - pad * 1.5 - tgw, ty);
}
